def simhash(text):
    v = [0]*64
    for tok, w in weighted_shingles(normalize(text)):
        h = hash64(tok)
        for i in range(64):
            v[i] += w if (h >> i) & 1 else -w
    return sum(1 << i for i in range(64) if v[i] > 0)

def query(h):
    cands = set()
    for b in range(4):
        cands |= table[b].get((h >> (16*b)) & 0xFFFF, [])
    return [c for c in cands if popcount(c.hash ^ h) <= 3]
